'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
const graph = Array.from({ length: n + 1 }, () => []);
let index = 1;

for (let i = 0; i < n - 1; i++) {
  const a = input[index++];
  const b = input[index++];
  graph[a].push(b);
  graph[b].push(a);
}

const parent = new Int32Array(n + 1);
const order = new Int32Array(n);
const stack = [1];
let count = 0;

parent[1] = -1;

while (stack.length > 0) {
  const node = stack.pop();
  order[count++] = node;

  for (const next of graph[node]) {
    if (next !== parent[node]) {
      parent[next] = node;
      stack.push(next);
    }
  }
}

const subtree = new Int32Array(n + 1);
subtree.fill(1);

let answer = n;

for (let i = n - 1; i > 0; i--) {
  const node = order[i];
  const size = subtree[node];
  answer = Math.min(answer, Math.abs(n - 2 * size));
  subtree[parent[node]] += size;
}

console.log(answer);
